ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS name_en text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS name_am text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS name_om text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS sort_order integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS is_visible boolean NOT NULL DEFAULT true;
UPDATE public.categories SET name_en=name,sort_order=display_order,is_visible=active WHERE name_en='';
ALTER TABLE public.categories ALTER COLUMN name SET DEFAULT '';
CREATE TABLE public.menu_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES public.categories(id), name_en text NOT NULL, name_am text NOT NULL DEFAULT '', name_om text NOT NULL DEFAULT '', description_en text NOT NULL DEFAULT '', description_am text NOT NULL DEFAULT '', description_om text NOT NULL DEFAULT '', ingredients text NOT NULL DEFAULT '', ingredients_am text NOT NULL DEFAULT '', ingredients_om text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL CHECK(price>=0), image_url text, dietary_tags text[] NOT NULL DEFAULT '{}', allergens text[] NOT NULL DEFAULT '{}', is_available boolean NOT NULL DEFAULT true, is_featured boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, photo_confirmed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.menu_items TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.menu_items TO authenticated; GRANT ALL ON public.menu_items TO service_role;
ALTER TABLE public.menu_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY menu_public_read ON public.menu_items FOR SELECT TO anon,authenticated USING(is_available AND EXISTS(SELECT 1 FROM public.categories c WHERE c.id=category_id AND c.is_visible));
CREATE POLICY menu_admin_all ON public.menu_items FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX menu_category_sort ON public.menu_items(category_id,sort_order);
CREATE TABLE public.settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), hotel_name text NOT NULL DEFAULT 'Bulcha International Hotel', logo_url text, vat_percent numeric NOT NULL DEFAULT 15 CHECK(vat_percent>=0 AND vat_percent<=100), currency text NOT NULL DEFAULT 'ETB', opening_hours text NOT NULL DEFAULT '', wifi_name text NOT NULL DEFAULT '', wifi_password text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', languages text[] NOT NULL DEFAULT ARRAY['en','am','om'], default_language text NOT NULL DEFAULT 'en');
GRANT SELECT ON public.settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.settings TO authenticated; GRANT ALL ON public.settings TO service_role;
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_public_read ON public.settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY settings_admin_all ON public.settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS table_or_room text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS items jsonb NOT NULL DEFAULT '[]', ADD COLUMN IF NOT EXISTS vat numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS submission_id uuid UNIQUE;
ALTER TABLE public.orders ALTER COLUMN customer_name SET DEFAULT 'Hotel guest'; ALTER TABLE public.orders ALTER COLUMN status SET DEFAULT 'new';
DROP POLICY IF EXISTS "Public read categories" ON public.categories;
CREATE POLICY categories_public_visible ON public.categories FOR SELECT TO anon,authenticated USING(is_visible);
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
DROP POLICY IF EXISTS "Staff update orders" ON public.orders; DROP POLICY IF EXISTS "Users view own orders" ON public.orders;
CREATE POLICY orders_admin_read ON public.orders FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY orders_admin_update ON public.orders FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
REVOKE SELECT,UPDATE,DELETE ON public.orders FROM anon; GRANT INSERT ON public.orders TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.orders TO authenticated;
CREATE OR REPLACE FUNCTION public.validate_menu_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE line jsonb; dish public.menu_items%ROWTYPE; q integer; sum_total numeric:=0; rate numeric; normalized jsonb:='[]';
BEGIN
 IF NEW.items='[]'::jsonb THEN RAISE EXCEPTION 'Choose at least one menu item'; END IF;
 IF char_length(trim(NEW.table_or_room))=0 OR char_length(NEW.table_or_room)>80 THEN RAISE EXCEPTION 'Enter a table or room number'; END IF;
 IF jsonb_typeof(NEW.items)<>'array' OR jsonb_array_length(NEW.items)>100 THEN RAISE EXCEPTION 'Invalid order'; END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(NEW.items) LOOP
  SELECT * INTO dish FROM public.menu_items WHERE id=(line->>'id')::uuid AND is_available;
  IF NOT FOUND THEN RAISE EXCEPTION 'An item is no longer available'; END IF;
  q:=(line->>'quantity')::integer;
  IF q<1 OR q>50 THEN RAISE EXCEPTION 'Quantity must be between 1 and 50'; END IF;
  sum_total:=sum_total+dish.price*q;
  normalized:=normalized||jsonb_build_array(jsonb_build_object('id',dish.id,'name',dish.name_en,'price',dish.price,'quantity',q,'note',left(coalesce(line->>'note',''),500),'image_url',dish.image_url));
 END LOOP;
 SELECT vat_percent INTO rate FROM public.settings WHERE id=true; rate:=coalesce(rate,15);
 NEW.items:=normalized; NEW.subtotal:=round(sum_total,2); NEW.vat:=round(sum_total*rate/100,2); NEW.tax:=NEW.vat; NEW.total:=NEW.subtotal+NEW.vat; NEW.status:='new'; NEW.user_id:=NULL; NEW.discount:=0; NEW.note:=left(NEW.note,1000);
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.validate_menu_order() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_menu_order BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.validate_menu_order();
REVOKE ALL ON FUNCTION public.get_order_summary(uuid),public.get_order_items(uuid),public.get_order_payment(uuid),public.place_order(text,text,uuid,boolean,text,jsonb),public.submit_payment(uuid,public.payment_method,text,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,phone) VALUES(NEW.id,NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'phone'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC,anon,authenticated;
CREATE POLICY menu_images_admin_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='menu-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY menu_images_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='menu-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY menu_images_admin_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='menu-images' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='menu-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY menu_images_admin_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='menu-images' AND public.has_role(auth.uid(),'admin'));
COMMENT ON TABLE public.foods IS 'Deprecated by premium menu_items; retained for historical order references.';
COMMENT ON TABLE public.restaurant_settings IS 'Deprecated by premium settings; retained for historical compatibility.';
